package com.telusko.placement_portal.service;
import com.telusko.placement_portal.entity.*;import com.telusko.placement_portal.repository.*;import com.telusko.placement_portal.security.UserPrincipal;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class AdminSettingsService {
 private final PortalSettingsRepo settings;private final UserRepository users;private final PasswordEncoder encoder;private final AdminAuditService audit;
 public AdminSettingsService(PortalSettingsRepo s,UserRepository u,PasswordEncoder e,AdminAuditService a){settings=s;users=u;encoder=e;audit=a;}
 @Transactional(readOnly=true) public Map<String,Object> getSettings(){PortalSettings p=settings.findAll().stream().findFirst().orElseGet(PortalSettings::new);return dto(p);}
 @Transactional public Map<String,Object> update(Map<String,Object> body,UserPrincipal admin){PortalSettings p=settings.findAll().stream().findFirst().orElseGet(PortalSettings::new);String name=str(body,"portalName",p.getPortalName(),120),desc=str(body,"description",p.getDescription(),1000),year=str(body,"academicYear",p.getAcademicYear(),80);boolean enabled=body.containsKey("applicationsEnabled")?Boolean.parseBoolean(String.valueOf(body.get("applicationsEnabled"))):p.isApplicationsEnabled();p.setPortalName(name);p.setDescription(desc);p.setAcademicYear(year);p.setApplicationsEnabled(enabled);PortalSettings saved=settings.save(p);audit.record(admin,"SETTINGS_UPDATED","PORTAL_SETTINGS",saved.getId(),"Portal settings updated",null,"portalName,description,academicYear,applicationsEnabled");return dto(saved);}
 @Transactional(readOnly=true) public Map<String,Object> profile(UserPrincipal principal){User u=require(principal.getId());return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole());}
 @Transactional public Map<String,Object> updateProfile(Map<String,String> body,UserPrincipal principal){User u=require(principal.getId());String name=body.get("name");if(name==null||name.isBlank()||name.trim().length()>120)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name is required and must be at most 120 characters.");u.setName(name.trim());users.save(u);audit.record(principal,"ADMIN_PROFILE_UPDATED","USER",u.getId(),"Administrator profile name updated",null,"name updated");return profile(principal);}
 @Transactional public void changePassword(Map<String,String> body,UserPrincipal principal){User u=require(principal.getId());String current=body.get("currentPassword"),next=body.get("newPassword");if(current==null||next==null||next.length()<10||next.length()>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter the current password and a new password of 10–72 characters.");if(!encoder.matches(current,u.getPassword()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");u.setPassword(encoder.encode(next));users.save(u);audit.record(principal,"ADMIN_PASSWORD_CHANGED","USER",u.getId(),"Administrator password changed",null,"password changed");}
 private User require(Long id){return users.findById(id).filter(u->"ADMIN".equalsIgnoreCase(u.getRole())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Administrator not found."));}
 private String str(Map<String,Object>b,String k,String d,int max){Object x=b.get(k);String v=x==null?d:String.valueOf(x).trim();if(v.length()>max||(k.equals("portalName")&&v.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid "+k+".");return v;}
 private Map<String,Object> dto(PortalSettings p){Map<String,Object> m=new LinkedHashMap<>();m.put("portalName",p.getPortalName());m.put("description",p.getDescription());m.put("academicYear",p.getAcademicYear());m.put("applicationsEnabled",p.isApplicationsEnabled());return m;}
}
